// SPDX-License-Identifier: Apache-2.0
//! Refund authorization and idempotency.
pub fn authorize_refund(amount_cents: u64, daily_limit: u64) -> bool { amount_cents <= daily_limit }
pub fn refund_idempotency_key(payment_id: &str) -> String { format!("refund:{payment_id}") }

sources.src/sessions.rs:
// SPDX-License-Identifier: Apache-2.0
//! Revoke account sessions after credential recovery.
pub struct Session { pub revoked: bool }
pub fn revoke_session(session: &mut Session) { session.revoked = true; }

sources.src/retry.rs:
// SPDX-License-Identifier: Apache-2.0
//! Backoff for transient transport failures.
pub fn retry_delay_ms(attempt: u32) -> u64 { 25 * (1_u64 << attempt.min(4)) }
